PATTERNS = [
    [r"(\d[\d.,]*[KMB]?) eigen regels\.", "$1 custom rules."],
    [r"(\d+) lijsten ingeschakeld\.", "$1 lists turned on."],
    [r"(\d+) van (\d+) lijsten ingeschakeld op (.+)", "$1 of $2 lists turned on on $3"],
    [r"(\d[\d.,]*[KMB]?) regels, bijgewerkt (.+)", "$1 rules, updated $2"],
    [r"(\d[\d.,]*[KMB]?) regels", "$1 rules"],
    [r"bijgewerkt (.+)", "updated $1"],
    [r"\((\d+)%\) van", "($1%) of"],
    [r"van (\d[\d.,]*[KMB]?)", "of $1"],
    [r"Blokkeerlijsten \((\d+)\)", "Blocklists ($1)"],
    [r"Gebruikersregels \((\d+)\)", "User rules ($1)"],
    [r"Gebruikersregels (.+)", "User rules $1"],
    [r"Apparaten (\d+)", "Devices $1"],
    [r"Bescherming voor (.+)", "Protection for $1"],
    [r"Acties voor (.+)", "Actions for $1"],
    [r"(.+): (\d[\d.,]*[KMB]?) verzoeken", "$1: $2 requests"],
    [r"(\d[\d.,]*[KMB]?) verzoeken", "$1 requests"],
    [r"(\d[\d.,]*[KMB]?) geblokkeerd \((\d+)%\)", "$1 blocked ($2%)"],
    [r"(\d+) bedrijven", "$1 companies"],
    [r"Verzoeken, (.+)", "Requests, $1"],
    [r"afgelopen 24 uur", "last 24 hours"], [r"afgelopen 7 dagen", "last 7 days"], [r"afgelopen 30 dagen", "last 30 days"],
    [r"Laatst ververst: (.+)", "Last refreshed: $1"],
    [r"Volgende betaling: (.+)", "Next payment: $1"],
    [r"([^ ]+(?: of iPad)?) op (.+)", "$1 on $2"],
    [r"worden geblokkeerd voor alle apparaten op (.+)\. Dit wordt een gebruikersregel die je altijd weer kunt verwijderen\.",
     "will be blocked for all devices on $1. This becomes a user rule that you can always remove."],
    [r"worden niet meer geblokkeerd voor alle apparaten op (.+)\. Dit wordt een gebruikersregel die je altijd weer kunt verwijderen\.",
     "will no longer be blocked for all devices on $1. This becomes a user rule that you can always remove."],
    [r"(.+) Het kan een minuut duren voordat het overal werkt\.", "$1 It may take a minute before it works everywhere."],
    [r"Ongeldige waarde voor (.+)\.", "Invalid value for $1."],
    [r"AdGuard DNS gaf een fout: HTTP (\d+)\.", "AdGuard DNS returned an error: HTTP $1."],
    [r"AdGuard DNS is niet bereikbaar \((.+)\)\.", "AdGuard DNS is not reachable ($1)."],
    [r"Bedrijf (\d+)", "Company $1"],
]
